import{_ as t,a0 as p,w as o,s as h,ao as d,I as n,x as a,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"探索 Shell 腳本的威力 | LCTT x X-CMD","titleTemplate":false,"description":"探索 Shell 腳本的威力 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"探索 Shell 腳本的威力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"探索 Shell 腳本的威力 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20220526 Shell Scripting is Still Going Strong","title":"探索 Shell 腳本的威力","tag":"202307","desc":""},"relativePath":"202307/20220526 Shell Scripting is Still Going Strong.md","filePath":"[post].md"}'),c={name:"202307/20220526 Shell Scripting is Still Going Strong.md"};function r(g,s,k,b,u,f){const e=p("Link");return o(),h("div",null,[s[13]||(s[13]=d(`<h1 id="探索-shell-腳本的威力" tabindex="-1">探索 Shell 腳本的威力 <a class="header-anchor" href="#探索-shell-腳本的威力" aria-label="Permalink to “探索 Shell 腳本的威力”">​</a></h1><blockquote><p>本文章向你介紹了 Shell 腳本的基礎知識以及其在日常生活中的重要性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202307/31/070953kv0kdvld33h55uk5.jpg" alt=""></p><p>當我們登錄到一個 UNIX/Linux 系統時，我們首先注意到的是閃爍的光標和 <code>$</code> 符號之間的空格。這就是 Shell（交互界面）。多年來，它一直是一種無處不在（有時甚至是唯一的）與計算機交互的界面。在圖形用户界面（GUI）出現和流行之前，終端和 Shell 是唯一的機制，可以讓計算機按照我們的意圖進行操作。乍一看，我們可能會想知道 Shell 的作用，除了將命令傳遞給底層操作系統以進行執行之外。我們中的大多數人熟悉像 <code>ls</code>（用於列出目錄內容），<code>cd</code>（用於更改當前目錄）等命令。通過 Shell，我們可以執行這些命令。Shell 理解我們輸入的文本 - 將其轉換為標記 - 然後在操作系統上執行這些標記。</p><h3 id="不同的-shell-變種" tabindex="-1">不同的 Shell 變種 <a class="header-anchor" href="#不同的-shell-變種" aria-label="Permalink to “不同的 Shell 變種”">​</a></h3><p>最初，終端使用了樸素的 Bourne Shell（即 Sh）。多年來，許多不同的 Shell 變種被開發出來和使用。其中一些流行的包括 C Shell（Csh） 和 Korn Shell（Ksh）。Sh 在一段時間內不再受歡迎，但通過其最新的化身 —— Bourne Again Shell（Bash），它再次流行起來。</p><h3 id="shell-實際上是做什麼的" tabindex="-1">Shell 實際上是做什麼的？ <a class="header-anchor" href="#shell-實際上是做什麼的" aria-label="Permalink to “Shell 實際上是做什麼的？”">​</a></h3><p>Shell 是操作系統（OS）和用户之間的直接接口。通過使用命令和應用程序來使用計算機上安裝的工具，我們可以使計算機按照我們的意願工作。一些命令是安裝在操作系統上的應用程序，而某些命令則是直接內置在 Shell 中的。在 Bash 中內置的一些命令包括 <code>clear</code>、<code>cd</code>、<code>eval</code> 和 <code>exec</code>，還有 <code>ls</code> 和 <code>mkdir</code> 這樣的應用程序。內置在 Shell 中的命令因 Shell 而異。</p><p>在本文中，我們將涵蓋與 Bash 相關的幾個方面。</p><h3 id="更多關於-shell-的內容" tabindex="-1">更多關於 Shell 的內容 <a class="header-anchor" href="#更多關於-shell-的內容" aria-label="Permalink to “更多關於 Shell 的內容”">​</a></h3><p>我們中的大多數人都用過像 <code>ls</code>、<code>cd</code> 和 <code>mkdir</code> 這樣的命令。當我們在一個目錄上運行 <code>ls -l</code> 命令時，該目錄中的所有子目錄和文件都會在屏幕上列出。如果數量很大，屏幕會滾動。如果終端不支持滾動條（在很多年裏都是如此），則無法查看已滾動過的條目。為了克服這個問題，我們使用像 <code>more</code> 和 <code>less</code> 這樣的命令。它們允許我們逐頁查看輸出。通常使用的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l | less</span></span></code></pre></div><p>在這裏 Shell 是在做什麼？看起來像是單個命令，實際上是 <code>ls</code> 和 <code>less</code> 兩個命令依次執行。管道符（<code>|</code>）將這兩個程序連接起來，但連接由 Shell 管理。由於有了管道符，Shell 連接了這兩個程序——它將 <code>ls</code> 命令的標準輸出連接到 <code>less</code> 的標準輸入（stdin）。管道功能使我們能夠將任何程序的輸出作為另一個程序的輸入提供，而無需對程序進行任何更改。這是許多 UNIX/Linux 應用程序的理念——保持應用程序簡單，然後將許多應用程序組合在一起以實現最終結果，而不是讓一個程序做很多事情。</p><p>如果需要，我們可以將 <code>ls</code> 的輸出重定向到文件中，然後使用 <code>vi</code> 查看它。為此，我們使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -l &gt; /tmp/my_file.txt</span></span>
<span class="line"><span>vi /tmp/my_file.txt</span></span></code></pre></div><p>在這種情況下，<code>ls</code> 的輸出被重定向到一個文件中。這由 Shell 進行管理，它理解 <code>&gt;</code> 符號表示重定向。它將其後面的標記視為文件。</p><h3 id="使用-shell-自動化" tabindex="-1">使用 Shell 自動化 <a class="header-anchor" href="#使用-shell-自動化" aria-label="Permalink to “使用 Shell 自動化”">​</a></h3><p>結合命令的能力是使用 Shell 命令創建自動化腳本的關鍵要素之一。在我最近的項目中，我們使用集羣模式執行 Python/Spark（PySpark）應用程序。每個應用程序執行了許多結構化查詢語言（SQL）語句 - SparkSQL。為了跟蹤應用程序的進展，我們會打印有關正在執行的 SQL 的詳細信息。這樣可以讓我們保留應用程序中正在發生的情況的日誌。由於應用程序在集羣模式下執行，要查看日誌，我們必須使用以下 <code>yarn</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yarn log –applicationId [application_id]</span></span></code></pre></div><p>在大多數情況下，應用程序生成的日誌非常大。因此，我們通常將日誌導入到 <code>less</code> 中，或將其重定向到一個文件中。我們使用的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yarn log –aplicationId [application_id] | less</span></span></code></pre></div><p>我們的開發團隊有 40 人。每個人都必須記住這個命令。為了簡化操作，我將這個命令轉換成了一個 Bash 腳本。為此，我創建了一個以 <code>.sh</code> 為擴展名的文件。在 UNIX 和 Linux 系統上，文件擴展名並不重要。只要文件是可執行的，它就能工作。擴展名在 MS Windows 上有意義。</p><h3 id="需要記住的重要事項" tabindex="-1">需要記住的重要事項 <a class="header-anchor" href="#需要記住的重要事項" aria-label="Permalink to “需要記住的重要事項”">​</a></h3><p>Shell 是一個解釋器。這意味着它會逐行讀取程序並執行它。這種方法的限制在於錯誤（如果有）在事先無法被識別。直到解釋器讀取和執行它們時，錯誤才會被識別出來。簡而言之，假如我們有一個在前 20 行完美執行，但在第 21 行由於語法錯誤而失敗的 Shell 程序。當腳本在第 21 行失敗時，Shell 不會回滾/撤銷之前的步驟。當發生這樣的情況時，我們必須糾正腳本並從第一行開始執行。因此，例如，如果在遇到錯誤之前刪除了幾個文件，腳本的執行將停止，而文件將永遠消失。</p><p>我創建的腳本是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>yarn log –applicationId 123 | less</span></span></code></pre></div><p>…其中 123 是應用程序的 ID。</p><p>第一行的前兩個字符是特殊字符（“釋伴”）。它們告訴腳本這是一個可執行文件，並且該行包含要用於執行的程序的名稱。腳本的其餘行傳遞給所提到的程序。在這個例子中，我們將執行 Bash。即使包含了第一行，我們仍然必須使用以下命令對文件應用執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod +x my_file.sh</span></span></code></pre></div><p>在給文件設置了執行權限之後，我們可以如下執行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_file.sh</span></span></code></pre></div><p>如果我們沒有給文件設置執行權限，我們可以使用以下命令執行該腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sh ./my_file.sh</span></span></code></pre></div><h3 id="傳遞參數" tabindex="-1">傳遞參數 <a class="header-anchor" href="#傳遞參數" aria-label="Permalink to “傳遞參數”">​</a></h3><p>你很快就會意識到，這樣的腳本很方便，但立即變得無用。每次執行 Python/Spark 應用程序時，都會生成一個新的 ID。因此，對於每次運行，我們都必須編輯文件並添加新的應用程序 ID。這無疑降低了腳本的可用性。為了提高其可用性，我們應該將應用程序 ID 作為參數傳遞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>yarn –log -applicationId \${1} | less</span></span></code></pre></div><p>我們需要這樣執行腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./show_log.sh 123</span></span></code></pre></div><p>腳本將執行 <code>yarn</code> 命令，獲取應用程序的日誌並允許我們查看它。</p><p>如果我們想將輸出重定向到一個文件中怎麼辦？沒問題。我們可以將輸出重定向到一個文件而不是發送給 <code>less</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>ls –l \${1} &gt; \${2}</span></span>
<span class="line"><span>view \${2}</span></span></code></pre></div><p>要運行腳本，我們需要提供兩個參數，命令變為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_file.sh /tmp /tmp/listing.txt</span></span></code></pre></div><p>當執行時，<code>$1</code> 將綁定到 <code>/tmp</code>，<code>$2</code> 將綁定到 <code>/tmp/listing.txt</code>。對於 Shell，參數從一到九命名。這並不意味着我們不能將超過九個參數傳遞給腳本。我們可以，但這是另一篇文章的主題。你會注意到，我將參數命名為 <code>\${1}</code> 和 <code>\${2}</code>，而不是 <code>$1</code> 和 <code>$2</code>。將參數名稱封閉在花括號中是一個好習慣，因為它使我們能夠無歧義地將參數作為較長變量的一部分組合起來。例如，我們可以要求用户將文件名作為參數，並使用它來形成一個更大的文件名。例如，我們可以將 <code>$1</code> 作為參數，創建一個新的文件名為 <code>\${1}_student_names.txt</code>。</p><h3 id="使腳本更健壯" tabindex="-1">使腳本更健壯 <a class="header-anchor" href="#使腳本更健壯" aria-label="Permalink to “使腳本更健壯”">​</a></h3><p>如果用户忘記提供參數怎麼辦？Shell 允許我們檢查這種情況。我們將腳本修改如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>if [ -z &quot;\${2}&quot; ]; then</span></span>
<span class="line"><span>  echo &quot;file name not provided&quot;</span></span>
<span class="line"><span>  exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>if [ -z &quot;\${1}&quot; ]; then</span></span>
<span class="line"><span>  echo &quot;directory name not provided&quot;</span></span>
<span class="line"><span>  exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>DIR_NAME=\${1}</span></span>
<span class="line"><span>FILE_NAME=\${2}</span></span>
<span class="line"><span>ls -l \${DIR_NAME} &gt; /tmp/\${FILE_NAME}</span></span>
<span class="line"><span>view /tmp/\${FILE_NAME}</span></span></code></pre></div><p>在這個程序中，我們檢查是否傳遞了正確的參數。如果未傳遞參數，我們將退出腳本。你會注意到，我以相反的順序檢查參數。如果我們在檢查第一個參數存在之前檢查第二個參數的存在，如果只傳遞了一個參數，腳本將進行到下一步。雖然可以按遞增順序檢查參數的存在，但我最近意識到，從九到一檢查會更好，因為我們可以提供適當的錯誤消息。你還會注意到，參數已分配給變量。參數一到九是位置參數。將位置參數分配給具名參數可以在出現問題時更容易調試腳本。</p><h3 id="自動化備份" tabindex="-1">自動化備份 <a class="header-anchor" href="#自動化備份" aria-label="Permalink to “自動化備份”">​</a></h3><p>我自動化的另一個任務是備份。在開發的初期階段，我們沒有使用版本控制系統。但我們需要有一個機制來定期備份。因此，最好的方法是編寫一個 Shell 腳本，在執行時將所有代碼文件複製到一個單獨的目錄中，將它們壓縮，並使用日期和時間作為後綴來上傳到 HDFS。我知道，這種方法不如使用版本控制系統那樣清晰，因為我們存儲了完整的文件，查找差異仍然需要使用像 <code>diff</code> 這樣的程序；但它總比沒有好。儘管我們最終沒有刪除代碼文件，但團隊確實刪除了存儲助手腳本的 <code>bin</code> 目錄！！！而且對於這個目錄，我沒有備份。我別無選擇，只能重新創建所有的腳本。</p><p>一旦建立了源代碼控制系統，我很容易將備份腳本擴展到除了之前上傳到 HDFS 的方法之外，還可以將文件上傳到版本控制系統。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如今，像 Python、Spark、Scala 和 Java 這樣的編程語言很受歡迎，因為它們用於開發與人工智能和機器學習相關的應用程序。儘管與 Shell 相比，這些語言更強大，但“不起眼”的 Shell 提供了一個即用即得的平台，讓我們能夠創建輔助腳本來簡化我們的日常任務。Shell 是相當強大的，尤其是因為我們可以結合操作系統上安裝的所有應用程序的功能。正如我在我的項目中發現的那樣，即使經過了幾十年，Shell 腳本仍然非常強大。我希望我已經説服你嘗試一下了。</p><h3 id="最後一個例子" tabindex="-1">最後一個例子 <a class="header-anchor" href="#最後一個例子" aria-label="Permalink to “最後一個例子”">​</a></h3><p>Shell 腳本確實非常方便。考慮以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>spark3-submit --queue pyspark --conf &quot;spark.yarn.principal=abcd@abcd.com&quot; --conf &quot;spark.yarn.keytab=/keytabs/abcd.keytab&quot; --jars /opt/custom_jars/abcd_1.jar --deploy-mode cluster --master yarn $*</span></span></code></pre></div><p>我們要求在執行 Python/Spark 應用程序時使用此命令。現在想像一下，這個命令必須每天被一個由 40 個人組成的團隊多次使用。大多數人會在記事本中複製這個命令，每次需要使用時，會將其從記事本中複製並粘貼到終端中。如果複製粘貼過程中出現錯誤怎麼辦？如果有人錯誤使用了參數怎麼辦？我們如何調試使用的是哪個命令？查看歷史記錄並沒有太多幫助。</p><p>為了讓團隊能夠簡單地執行 Python/Spark 應用程序，我們可以創建一個 Bash Shell 腳本，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>SERVICE_PRINCIPAL=abcd@abcd.com</span></span>
<span class="line"><span>KEYTAB_PATH=/keytabs/abcd.keytab</span></span>
<span class="line"><span>MY_JARS=/opt/custom_jars/abcd_1.jar</span></span>
<span class="line"><span>MAX_RETRIES=128</span></span>
<span class="line"><span>QUEUE=pyspark</span></span>
<span class="line"><span>MASTER=yarn</span></span>
<span class="line"><span>MODE=cluster</span></span>
<span class="line"><span></span></span>
<span class="line"><span>spark3-submit --queue \${QUEUE} --conf &quot;spark.yarn.principal=\${SERVICE_PRINCIPAL}&quot; --conf &quot;spark.yarn.keytab=\${KEYTAB_PATH}&quot; --jars \${MY_JARS} --deploy-mode \${MODE} --master \${MASTER} $*</span></span></code></pre></div><p>這展示了一個 Shell 腳本的強大之處，讓我們的生活變得簡單。根據你的需求，你可以嘗試更多的命令和腳本，並進一步探索。</p><p><em>（題圖：MJ/f32880e8-0cdc-4897-8a1c-242c131111bf）</em></p><hr>`,62)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),l(e,{href:"https://www.opensourceforu.com/2022/05/shell-scripting-is-still-going-strong/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.opensourceforu.com/2022/05/shell-scripting-is-still-going-strong/",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=a("作者：",-1)),l(e,{href:"https://www.opensourceforu.com/author/bipin-patwardhan/"},{default:i(()=>[...s[2]||(s[2]=[a("Bipin Patwardhan",-1)])]),_:1}),s[6]||(s[6]=a(" 選題：",-1)),l(e,{href:"https://github.com/lkxed"},{default:i(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[7]||(s[7]=a(" 譯者：ChatGPT 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const x=t(c,[["render",r]]);export{y as __pageData,x as default};
